blocks.v:
/* Base font size */
body {
  font-size: 16px;
}

/* Parent element */
.container {
  font-size: 1.5em; /* 1.5 * 16px = 24px */
}

/* Child element */
.container .child {
  font-size: 2em; /* 2 * 24px = 48px */
}

/* Base font size */
html {
  font-size: 16px;
}

/* Element sizes */
h1 {
  font-size: 2rem; /* 2 * 16px = 32px */
}

p {
  font-size: 1rem; /* 1 * 16px = 16px */
}

html {
  font-size: 16px;
}

.card {
  font-size: 1rem; /* 16px */
  padding: 2em; /* 2 * 16px = 32px, relative to the card's font size */
}

.card-title {
  font-size: 1.5rem; /* 1.5 * 16px = 24px, relative to the root */
}
